mapper.select:
SELECT r.id, r.review_id, r.task_id, r.thread_id, r.review_object, r.query_id,
       r.risk_level, r.decision, r.comment, r.reviewer_id, r.review_round,
       r.create_time, r.update_time, r.is_deleted
FROM rcagent_attribution_review_log r
INNER JOIN rcagent_attribution_task t ON r.task_id = t.task_id

    r.is_deleted = 0
    AND t.is_deleted = 0


            AND t.ds_id = #{q.dsId}


            AND r.task_id = #{q.taskId}


            AND r.review_object = #{q.reviewObject}


            AND r.decision = #{q.decision}



ORDER BY r.create_time DESC, r.id DESC
